import type * as React from "react";

export type NavItem = {
  title: string;
  href: string;
  icon?: React.ComponentType<{ className?: string }>;
  /** Count or label shown at the right, e.g. unread messages. Hidden when 0. */
  badge?: number | string;
  /** Only active on this exact path (use for the dashboard home). */
  exact?: boolean;
  /** Sub-pages, shown as a collapsible sub-menu. */
  items?: NavItem[];
};

export type NavSection = {
  /** Optional heading, e.g. "Settings". */
  label?: string;
  items: NavItem[];
};

/**
 * Whether `href` is the current page or one of its children.
 * Matches on path segments, so /dashboard/notes is not active on /dashboard/notes-archive.
 */
export function isActive(pathname: string, href: string, exact = false): boolean {
  if (pathname === href) return true;
  if (exact) return false;
  const base = href.endsWith("/") ? href : `${href}/`;
  return pathname.startsWith(base);
}

/** The chain of nav items leading to the current page, deepest match last. */
export function findTrail(sections: NavSection[], pathname: string): NavItem[] {
  // Every active item extends the trail; keep the one whose page is most specific.
  let best: NavItem[] = [];
  const walk = (items: NavItem[], trail: NavItem[]) => {
    for (const item of items) {
      if (!isActive(pathname, item.href, item.exact)) continue;
      const next = [...trail, item];
      if (item.href.length > (best.at(-1)?.href.length ?? -1)) best = next;
      if (item.items) walk(item.items, next);
    }
  };
  for (const section of sections) walk(section.items, []);
  return best;
}

"use client";

import * as React from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { ChevronRight, ChevronsUpDown, LogOut } from "lucide-react";

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuBadge,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarMenuSub,
  SidebarMenuSubButton,
  SidebarMenuSubItem,
  SidebarRail,
} from "@/components/ui/sidebar";
import { isActive, type NavItem, type NavSection } from "@/components/dashboard/nav";

export type SidebarUser = { name: string; email?: string; avatarUrl?: string };

export interface AppSidebarProps {
  brand: { name: string; subtitle?: string; logo?: React.ReactNode; href?: string };
  sections: NavSection[];
  user?: SidebarUser;
  onSignOut?: () => void | Promise<void>;
  /** Extra <DropdownMenuItem>s shown above "Sign out" in the user menu. */
  userMenu?: React.ReactNode;
}

export function AppSidebar({ brand, sections, user, onSignOut, userMenu }: AppSidebarProps) {
  const pathname = usePathname() ?? "";

  return (
    <Sidebar collapsible="icon">
      <SidebarHeader>
        <SidebarMenu>
          <SidebarMenuItem>
            <SidebarMenuButton size="lg" asChild>
              <Link href={brand.href ?? "/dashboard"}>
                <span className="flex aspect-square size-8 shrink-0 items-center justify-center rounded-lg bg-sidebar-primary text-sidebar-primary-foreground">
                  {brand.logo ?? <span className="text-sm font-bold">{brand.name.charAt(0)}</span>}
                </span>
                <span className="grid flex-1 text-left leading-tight">
                  <span className="truncate font-semibold">{brand.name}</span>
                  {brand.subtitle && <span className="truncate text-xs text-sidebar-foreground/70">{brand.subtitle}</span>}
                </span>
              </Link>
            </SidebarMenuButton>
          </SidebarMenuItem>
        </SidebarMenu>
      </SidebarHeader>

      <SidebarContent>
        {sections.map((section, i) => (
          <SidebarGroup key={section.label ?? i}>
            {section.label && <SidebarGroupLabel>{section.label}</SidebarGroupLabel>}
            <SidebarMenu>
              {section.items.map((item) => (
                <NavMenuItem key={item.href} item={item} pathname={pathname} />
              ))}
            </SidebarMenu>
          </SidebarGroup>
        ))}
      </SidebarContent>

      {user && (
        <SidebarFooter>
          <UserMenu user={user} onSignOut={onSignOut}>
            {userMenu}
          </UserMenu>
        </SidebarFooter>
      )}
      <SidebarRail />
    </Sidebar>
  );
}

function NavMenuItem({ item, pathname }: { item: NavItem; pathname: string }) {
  const active = isActive(pathname, item.href, item.exact);
  const Icon = item.icon;
  const showBadge = item.badge !== undefined && item.badge !== 0 && item.badge !== "";

  if (!item.items?.length) {
    return (
      <SidebarMenuItem>
        <SidebarMenuButton asChild isActive={active} tooltip={item.title}>
          <Link href={item.href}>
            {Icon && <Icon />}
            <span>{item.title}</span>
          </Link>
        </SidebarMenuButton>
        {showBadge && <SidebarMenuBadge>{item.badge}</SidebarMenuBadge>}
      </SidebarMenuItem>
    );
  }

  return (
    <Collapsible asChild defaultOpen={active} className="group/collapsible">
      <SidebarMenuItem>
        <CollapsibleTrigger asChild>
          <SidebarMenuButton isActive={active} tooltip={item.title}>
            {Icon && <Icon />}
            <span>{item.title}</span>
            <ChevronRight className="ml-auto transition-transform duration-200 group-data-[state=open]/collapsible:rotate-90" />
          </SidebarMenuButton>
        </CollapsibleTrigger>
        <CollapsibleContent>
          <SidebarMenuSub>
            {item.items.map((sub) => (
              <SidebarMenuSubItem key={sub.href}>
                <SidebarMenuSubButton asChild isActive={isActive(pathname, sub.href, sub.exact)}>
                  <Link href={sub.href}>
                    <span>{sub.title}</span>
                    {sub.badge !== undefined && sub.badge !== 0 && (
                      <span className="ml-auto text-xs tabular-nums text-sidebar-foreground/70">{sub.badge}</span>
                    )}
                  </Link>
                </SidebarMenuSubButton>
              </SidebarMenuSubItem>
            ))}
          </SidebarMenuSub>
        </CollapsibleContent>
      </SidebarMenuItem>
    </Collapsible>
  );
}

function initials(name: string) {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((p) => p[0]!.toUpperCase())
    .join("");
}

function UserMenu({
  user,
  onSignOut,
  children,
}: {
  user: SidebarUser;
  onSignOut?: () => void | Promise<void>;
  children?: React.ReactNode;
}) {
  const avatar = (
    <Avatar className="size-8 rounded-lg">
      {user.avatarUrl && <AvatarImage src={user.avatarUrl} alt="" />}
      <AvatarFallback className="rounded-lg">{initials(user.name)}</AvatarFallback>
    </Avatar>
  );
  const identity = (
    <span className="grid flex-1 text-left text-sm leading-tight">
      <span className="truncate font-medium">{user.name}</span>
      {user.email && <span className="truncate text-xs text-sidebar-foreground/70">{user.email}</span>}
    </span>
  );

  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <SidebarMenuButton size="lg" tooltip={user.name}>
              {avatar}
              {identity}
              <ChevronsUpDown className="ml-auto size-4" />
            </SidebarMenuButton>
          </DropdownMenuTrigger>
          <DropdownMenuContent side="top" align="start" className="min-w-56 rounded-lg">
            <DropdownMenuLabel className="flex items-center gap-2 font-normal">
              {avatar}
              {identity}
            </DropdownMenuLabel>
            {children && (
              <>
                <DropdownMenuSeparator />
                {children}
              </>
            )}
            {onSignOut && (
              <>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={() => void onSignOut()}>
                  <LogOut />
                  Sign out
                </DropdownMenuItem>
              </>
            )}
          </DropdownMenuContent>
        </DropdownMenu>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";

import * as React from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";

import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";
import { findTrail, type NavSection } from "@/components/dashboard/nav";

function titleCase(segment: string) {
  return decodeURIComponent(segment)
    .replace(/[-_]+/g, " ")
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

/**
 * Breadcrumbs for the current page. Uses nav titles where the path matches a
 * nav item, and title-cases the remaining URL segments (e.g. an [id] page).
 */
export function DashboardBreadcrumbs({
  sections,
  home = { title: "Dashboard", href: "/dashboard" },
}: {
  sections: NavSection[];
  home?: { title: string; href: string };
}) {
  const pathname = usePathname() ?? "";
  const trail = findTrail(sections, pathname).filter((item) => item.href !== home.href);

  const crumbs = trail.map((item) => ({ title: item.title, href: item.href }));
  const covered = crumbs.at(-1)?.href ?? home.href;
  if (pathname.startsWith(covered) && pathname.length > covered.length) {
    let href = covered.replace(/\/$/, "");
    for (const segment of pathname.slice(covered.length).split("/").filter(Boolean)) {
      href += `/${segment}`;
      crumbs.push({ title: titleCase(segment), href });
    }
  }

  return (
    <Breadcrumb>
      <BreadcrumbList>
        <BreadcrumbItem>
          {crumbs.length ? (
            <BreadcrumbLink asChild>
              <Link href={home.href}>{home.title}</Link>
            </BreadcrumbLink>
          ) : (
            <BreadcrumbPage>{home.title}</BreadcrumbPage>
          )}
        </BreadcrumbItem>
        {crumbs.map((crumb, i) => (
          <React.Fragment key={crumb.href}>
            <BreadcrumbSeparator />
            <BreadcrumbItem>
              {i === crumbs.length - 1 ? (
                <BreadcrumbPage>{crumb.title}</BreadcrumbPage>
              ) : (
                <BreadcrumbLink asChild>
                  <Link href={crumb.href}>{crumb.title}</Link>
                </BreadcrumbLink>
              )}
            </BreadcrumbItem>
          </React.Fragment>
        ))}
      </BreadcrumbList>
    </Breadcrumb>
  );
}

"use client";

import * as React from "react";

import { SidebarInset, SidebarProvider, SidebarTrigger } from "@/components/ui/sidebar";
import { AppSidebar, type AppSidebarProps } from "@/components/dashboard/app-sidebar";
import { DashboardBreadcrumbs } from "@/components/dashboard/dashboard-breadcrumbs";

export interface DashboardShellProps extends AppSidebarProps {
  children: React.ReactNode;
  /**
   * Whether the sidebar starts expanded. Read it from the `sidebar_state`
   * cookie in your server layout so the collapsed state survives reloads:
   *   (await cookies()).get("sidebar_state")?.value !== "false"
   */
  defaultOpen?: boolean;
  /** First breadcrumb (default: Dashboard → /dashboard). */
  home?: { title: string; href: string };
  /** Right side of the top bar, e.g. <ModeToggle /> or a search button. */
  actions?: React.ReactNode;
}

/**
 * Sidebar + top bar + content area for an app dashboard.
 * Collapses to icons on desktop (⌘/Ctrl+B or the rail), becomes a drawer on mobile.
 */
export function DashboardShell({
  children,
  defaultOpen = true,
  home,
  actions,
  ...sidebar
}: DashboardShellProps) {
  return (
    <SidebarProvider defaultOpen={defaultOpen}>
      <AppSidebar {...sidebar} />
      <SidebarInset>
        <header className="sticky top-0 z-10 flex h-14 shrink-0 items-center gap-2 border-b bg-background/95 px-4 backdrop-blur">
          <SidebarTrigger className="-ml-1" />
          <span aria-hidden="true" className="mr-2 h-4 w-px shrink-0 bg-border" />
          <DashboardBreadcrumbs sections={sidebar.sections} home={home} />
          {actions && <div className="ml-auto flex items-center gap-2">{actions}</div>}
        </header>
        <main className="flex-1 p-4 md:p-6">{children}</main>
      </SidebarInset>
    </SidebarProvider>
  );
}
